// Deterministic string hash (FNV-1a, 32-bit) -> no Math.random, stable per userId
function hashToBucket(userId) {
  let h = 0x811c9dc5;
  const s = String(userId);
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
  return h % 100;
}

function isEnabled(userId, rolloutPct) {
  return hashToBucket(userId) < rolloutPct;
}

const rolloutPct = 30;
const users = ['user-1', 'user-2', 'user-3', 'user-4', 'user-5', 'user-6', 'user-7', 'user-8'];
let on = 0;
for (const u of users) {
  const enabled = isEnabled(u, rolloutPct);
  if (enabled) on++;
  console.log(u + ' bucket=' + hashToBucket(u) + ' -> ' + (enabled ? 'ON' : 'OFF'));
}
console.log('ON count: ' + on + '/' + users.length);
